def summarize_orders(orders):
    from datetime import datetime
    monthly_totals = {}
    for order in orders:
        if datetime.strptime(order["date"], "%Y-%m-%d").date() >= datetime(2024, 1, 1).date():
            month = order["date"].split("-")[1]
            monthly_totals[month] = monthly_totals.get(month, 0) + order["amount"]
    return monthly_totals
